"""Ackermann coding explorer: every natural number IS a finite set."""
from __future__ import annotations


def mem(a: int, b: int) -> bool:
    """a is a member of b iff the a-th binary digit of b is 1."""
    return (b >> a) & 1 == 1


def members(b: int) -> list[int]:
    """The members of the set coded by b (indices of its set bits)."""
    return [a for a in range(b.bit_length()) if mem(a, b)]


def encode(s: set[int]) -> int:
    """Encode a finite set of naturals as sum of 2**a."""
    code = 0
    for a in s:
        code |= 1 << a
    return code


def show(b: int, depth: int = 4) -> str:
    """Render the set coded by b in braces notation."""
    if b == 0:
        return "{}"
    if depth == 0:
        return f"<{b}>"
    return "{" + ", ".join(show(x, depth - 1) for x in members(b)) + "}"


if __name__ == "__main__":
    for b in range(9):
        print(f"{b:>2} = {show(b)}")
    print("11 =", show(11))
    # round-trip
    s = {0, 2, 5}
    print("encode", s, "->", encode(s), "-> members", members(encode(s)))

"""Choice as a THEOREM in the finite universe: least-member selection."""
from __future__ import annotations


def members(b: int) -> list[int]:
    return [a for a in range(b.bit_length()) if (b >> a) & 1]


def least_member(b: int) -> int:
    """Index of the lowest set bit (number of trailing zeros); 0 for the empty set."""
    return 0 if b == 0 else (b & -b).bit_length() - 1


def replacement(a: int, f) -> int:
    """{ f(x) : x in a } as an Ackermann code."""
    s = 0
    for x in members(a):
        s |= 1 << f(x)
    return s


def choice_set(family: int) -> int:
    """A choice set for a family of nonempty pairwise-disjoint sets."""
    return replacement(family, least_member)


if __name__ == "__main__":
    b1, b2, b3 = 0, 0, 0
    for x in (3, 5):
        b1 |= 1 << x
    for x in (7, 9, 11):
        b2 |= 1 << x
    b3 |= 1 << 13
    family = (1 << b1) | (1 << b2) | (1 << b3)
    c = choice_set(family)
    print("family:", [members(b) for b in members(family)])
    print("choice set:", members(c))
    for b in members(family):
        hit = [x for x in members(c) if (b >> x) & 1]
        assert len(hit) == 1, "choice set must meet each member exactly once"
        print(f"  meets {members(b)} in exactly one point: {hit}")
    print("Axiom of Choice verified as a theorem.")

"""Rank and hereditary finiteness: the model lives inside V_omega."""
from __future__ import annotations


def members(b: int) -> list[int]:
    return [a for a in range(b.bit_length()) if (b >> a) & 1]


def transitive_closure(a: int) -> set[int]:
    seen: set[int] = set()
    stack = list(members(a))
    while stack:
        x = stack.pop()
        if x not in seen:
            seen.add(x)
            stack.extend(members(x))
    return seen


def rank(a: int, memo: dict[int, int] | None = None) -> int:
    """rank(a) = sup{ rank(x)+1 : x in a }, base 0."""
    if memo is None:
        memo = {}
    if a in memo:
        return memo[a]
    ms = members(a)
    r = 0 if not ms else max(rank(x, memo) + 1 for x in ms)
    memo[a] = r
    return r


if __name__ == "__main__":
    for b in [0, 1, 3, 11, 255, 1023]:
        tc = transitive_closure(b)
        print(f"code={b:>5}  rank={rank(b)}  |trans.closure|={len(tc):>3}  rank<=code: {rank(b) <= b}")

