"""Membership DAG of the initial segment of V_omega (codes 0..N)."""
import matplotlib.pyplot as plt


def members(b: int):
    return [a for a in range(b.bit_length()) if (b >> a) & 1]


def rank(a, memo):
    if a in memo:
        return memo[a]
    ms = members(a)
    r = 0 if not ms else max(rank(x, memo) + 1 for x in ms)
    memo[a] = r
    return r


def main(N: int = 16) -> None:
    memo: dict[int, int] = {}
    ranks = [rank(a, memo) for a in range(N)]
    # position nodes: x spread within a rank layer, y = rank
    from collections import defaultdict
    layers = defaultdict(list)
    for a in range(N):
        layers[ranks[a]].append(a)
    pos = {}
    for r, nodes in layers.items():
        for i, a in enumerate(nodes):
            pos[a] = (i - (len(nodes) - 1) / 2, r)
    fig, ax = plt.subplots(figsize=(9, 6))
    for b in range(N):
        for a in members(b):
            x0, y0 = pos[a]
            x1, y1 = pos[b]
            ax.annotate("", xy=(x1, y1), xytext=(x0, y0),
                        arrowprops=dict(arrowstyle="->", color="#8888ff", lw=0.8))
    for a in range(N):
        x, y = pos[a]
        ax.scatter([x], [y], s=420, color="#ffd54f", edgecolor="black", zorder=3)
        ax.text(x, y, str(a), ha="center", va="center", fontsize=9, zorder=4)
    ax.set_title("Membership DAG of V_omega (codes 0..15), layered by rank")
    ax.set_ylabel("rank")
    ax.set_xticks([])
